// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Agents create, edit and discard drafts"
// Changes: Draft store tests over an in-memory SQLite database with a fake clock: lifecycle, per-part revisions,
//          draft snapshots (auto, final) and their retention, cascade on project delete, duplicate without drafts.

import { beforeEach, describe, expect, it } from 'vitest'
import { readParts } from '#/lib/parts'
import { defaultProjectData, type ProjectData } from '#/lib/project'
import { openDatabase } from './db.server'
import { createProjectStore, type ProjectStore } from './projects.server'

const MINUTE = 60_000

let time: number
let store: ProjectStore
const advance = (ms: number) => {
  time += ms
}

beforeEach(() => {
  time = Date.parse('2026-01-01T10:00:00.000Z')
  store = createProjectStore(openDatabase(':memory:'), { now: () => new Date(time) })
})

const expressions = (): ProjectData => ({
  ...defaultProjectData(),
  def: { nonterminals: 'E', terminals: 'id +', start: 'E' },
  ll: { grammar: 'E -> id\nE -> id + E', input: 'id + id' },
  prec: { terminals: ['+', 'id'], cells: { 'id\u0001+': '>' }, rules: 'E -> E + E\nE -> id', input: 'id' },
  names: { map: 'id ID', ntPrefix: 'N_', tPrefix: 'T_', precPrefix: 'P_' },
})

const withGrammar = (data: ProjectData, grammar: string): ProjectData => ({ ...data, ll: { ...data.ll, grammar } })

describe('creating a draft', () => {
  it("an agent forks a draft from the project's current parts and the base point is recorded", () => {
    const project = store.createProject('Výrazy', expressions())
    store.saveProject(project.id, withGrammar(expressions(), 'E -> id'), 1)
    advance(1000)

    const draft = store.createDraft(project.id, '  Oprava konfliktu  ', 'agent')!
    expect(draft).toMatchObject({
      projectId: project.id,
      label: 'Oprava konfliktu',
      state: 'open',
      revision: 1,
      partRevisions: { definition: 1, grammarRules: 1, precTable: 1, reductionRules: 1 },
      lastChangedBy: 'agent',
      humanViewedRevision: 0,
      createdAt: '2026-01-01T10:00:01.000Z',
      updatedAt: '2026-01-01T10:00:01.000Z',
      endedAt: null,
    })
    const parts = readParts(withGrammar(expressions(), 'E -> id'))
    expect(draft.parts).toEqual(parts)
    expect(draft.base).toEqual({ projectRevision: 2, parts })
    expect(store.getDraft(draft.id)).toEqual(draft)
  })

  it('creating a draft never changes the project', () => {
    const project = store.createProject('Výrazy', expressions())
    store.createDraft(project.id, 'Návrh', 'agent')
    expect(store.getProject(project.id)).toEqual(project)
    expect(store.listSnapshots(project.id)).toEqual([])
  })

  it('a draft needs a label and an existing project', () => {
    const project = store.createProject('Výrazy', expressions())
    expect(() => store.createDraft(project.id, '  ', 'agent')).toThrow()
    expect(store.createDraft('nope', 'Návrh', 'agent')).toBeNull()
    expect(store.getDraft('nope')).toBeNull()
  })
})

describe('editing a draft', () => {
  it("an agent edits the grammar rules: the draft's revision and that part's revision move, the project stays", () => {
    const project = store.createProject('Výrazy', expressions())
    const draft = store.createDraft(project.id, 'Návrh', 'agent')!
    advance(1000)

    const result = store.editDraft(draft.id, { grammarRules: 'E -> id R\nR -> + E\nR -> eps' }, { author: 'agent' })
    expect(result.status).toBe('saved')
    if (result.status !== 'saved') return
    expect(result.changed).toEqual(['grammarRules'])
    expect(result.draft).toMatchObject({
      revision: 2,
      partRevisions: { definition: 1, grammarRules: 2, precTable: 1, reductionRules: 1 },
      lastChangedBy: 'agent',
      updatedAt: '2026-01-01T10:00:01.000Z',
    })
    expect(result.draft.parts.grammarRules).toBe('E -> id R\nR -> + E\nR -> eps')
    expect(result.draft.base.parts.grammarRules).toBe('E -> id\nE -> id + E')
    expect(store.getProject(project.id)).toEqual(project)
  })

  it('an edit can compute the new parts from the current ones (e.g. one precedence relation)', () => {
    const project = store.createProject('Výrazy', expressions())
    const draft = store.createDraft(project.id, 'Návrh', 'agent')!
    const result = store.editDraft(
      draft.id,
      (parts) => ({ precTable: { ...parts.precTable, cells: { ...parts.precTable.cells, '+\u0001id': '<' } } }),
      { author: 'agent' },
    )
    expect(result.status === 'saved' && result.draft.parts.precTable.cells).toEqual({ 'id\u0001+': '>', '+\u0001id': '<' })
  })

  it('an edit that changes nothing keeps the revision', () => {
    const project = store.createProject('Výrazy', expressions())
    const draft = store.createDraft(project.id, 'Návrh', 'agent')!
    const result = store.editDraft(draft.id, { reductionRules: draft.parts.reductionRules }, { author: 'agent' })
    expect(result).toMatchObject({ status: 'saved', changed: [], draft: { revision: 1 } })
  })

  it('a human edit marks the draft as changed by the human and seen by them', () => {
    const project = store.createProject('Výrazy', expressions())
    const draft = store.createDraft(project.id, 'Návrh', 'agent')!
    const result = store.editDraft(draft.id, { reductionRules: 'E -> id' }, { author: 'human' })
    expect(result).toMatchObject({ status: 'saved', draft: { revision: 2, lastChangedBy: 'human', humanViewedRevision: 2 } })
  })

  it('a stale base revision is a conflict only for parts someone else changed since then', () => {
    const project = store.createProject('Výrazy', expressions())
    const draft = store.createDraft(project.id, 'Návrh', 'agent')!
    store.editDraft(draft.id, { grammarRules: 'E -> id R' }, { author: 'agent' }) // revision 2

    // The human, still at revision 1, edits the reduction rules: no overlap, saved and merged.
    const merged = store.editDraft(draft.id, { reductionRules: 'E -> id' }, { author: 'human', baseRevision: 1 })
    expect(merged).toMatchObject({ status: 'saved', draft: { revision: 3 } })
    expect(merged.status === 'saved' && merged.draft.parts).toMatchObject({ grammarRules: 'E -> id R', reductionRules: 'E -> id' })

    // Another agent, also at revision 1, rewrites the grammar rules: overlap, refused.
    const refused = store.editDraft(draft.id, { grammarRules: 'E -> x' }, { author: 'agent', baseRevision: 1 })
    expect(refused).toMatchObject({ status: 'conflict', parts: ['grammarRules'], draft: { revision: 3 } })
    expect(store.getDraft(draft.id)!.parts.grammarRules).toBe('E -> id R')

    // At the current revision it goes through.
    expect(store.editDraft(draft.id, { grammarRules: 'E -> x' }, { author: 'agent', baseRevision: 3 }).status).toBe('saved')
  })

  it('relabelling keeps the revision; a draft that does not exist is missing', () => {
    const project = store.createProject('Výrazy', expressions())
    const draft = store.createDraft(project.id, 'Návrh', 'agent')!
    expect(store.relabelDraft(draft.id, ' Nová gramatika ')).toMatchObject({ status: 'saved', draft: { label: 'Nová gramatika', revision: 1 } })
    expect(() => store.relabelDraft(draft.id, ' ')).toThrow()
    expect(store.relabelDraft('nope', 'x')).toEqual({ status: 'missing' })
    expect(store.editDraft('nope', {}, { author: 'agent' })).toEqual({ status: 'missing' })
  })
})

describe('listing drafts', () => {
  it("lists a project's drafts, open ones first, then by last change", () => {
    const project = store.createProject('Výrazy', expressions())
    const other = store.createProject('Iný', expressions())
    const a = store.createDraft(project.id, 'A', 'agent')!
    advance(1000)
    const b = store.createDraft(project.id, 'B', 'agent')!
    advance(1000)
    const c = store.createDraft(project.id, 'C', 'human')!
    store.createDraft(other.id, 'X', 'agent')
    advance(1000)
    store.discardDraft(c.id)
    store.editDraft(a.id, { reductionRules: 'E -> id' }, { author: 'agent' })

    expect(store.listDrafts(project.id).map((d) => [d.label, d.state])).toEqual([
      ['A', 'open'],
      ['B', 'open'],
      ['C', 'discarded'],
    ])
    expect(store.listDrafts(project.id)[1]).toEqual({
      id: b.id,
      projectId: project.id,
      label: 'B',
      state: 'open',
      revision: 1,
      partRevisions: { definition: 1, grammarRules: 1, precTable: 1, reductionRules: 1 },
      lastChangedBy: 'agent',
      humanViewedRevision: 0,
      base: { projectRevision: 1 },
      createdAt: '2026-01-01T10:00:01.000Z',
      updatedAt: '2026-01-01T10:00:01.000Z',
      endedAt: null,
    })
  })
})

describe('discarding a draft', () => {
  it('ends the draft with a final snapshot of its last state; an ended draft is read-only', () => {
    const project = store.createProject('Výrazy', expressions())
    const draft = store.createDraft(project.id, 'Slepá ulička', 'agent')!
    store.editDraft(draft.id, { grammarRules: 'E -> x' }, { author: 'agent' })
    advance(1000)

    const result = store.discardDraft(draft.id)
    expect(result).toMatchObject({ status: 'saved', draft: { state: 'discarded', endedAt: '2026-01-01T10:00:01.000Z', revision: 2 } })

    const [final] = store.listDraftSnapshots(draft.id)
    expect(final).toMatchObject({ kind: 'final', label: 'Zahodený návrh „Slepá ulička“', createdAt: '2026-01-01T10:00:01.000Z' })
    expect(store.getSnapshot(final.id)).toMatchObject({ projectId: project.id, draftId: draft.id, data: { ll: { grammar: 'E -> x' } } })

    expect(store.editDraft(draft.id, { grammarRules: 'E -> y' }, { author: 'agent' })).toMatchObject({ status: 'ended' })
    expect(store.relabelDraft(draft.id, 'Iné')).toMatchObject({ status: 'ended', draft: { label: 'Slepá ulička' } })
    expect(store.discardDraft(draft.id)).toMatchObject({ status: 'ended' })
    expect(store.listDraftSnapshots(draft.id).map((s) => s.kind)).toEqual(['final', 'auto'])
    expect(store.getProject(project.id)).toEqual(project)
  })
})

describe('draft snapshots', () => {
  it('backs up the previous draft state at most every 20 minutes, apart from the project history', () => {
    const project = store.createProject('Výrazy', expressions())
    const draft = store.createDraft(project.id, 'Návrh', 'agent')!
    store.editDraft(draft.id, { grammarRules: 'v2' }, { author: 'agent' })
    advance(19 * MINUTE)
    store.editDraft(draft.id, { grammarRules: 'v3' }, { author: 'agent' })
    advance(1 * MINUTE)
    store.editDraft(draft.id, { grammarRules: 'v4' }, { author: 'agent' })

    const autos = store.listDraftSnapshots(draft.id)
    expect(autos.map((s) => [s.kind, s.createdAt])).toEqual([
      ['auto', '2026-01-01T10:20:00.000Z'],
      ['auto', '2026-01-01T10:00:00.000Z'],
    ])
    expect(store.getSnapshot(autos[0].id)!.data.ll.grammar).toBe('v3')
    expect(store.listSnapshots(project.id)).toEqual([])
    expect(store.listProjects()[0].snapshots).toBe(0)
  })

  it("keeps only the last 30 automatic snapshots of a draft, without pruning the project's", () => {
    const project = store.createProject('Výrazy', expressions())
    store.saveProject(project.id, withGrammar(expressions(), 'p2'), 1)
    const draft = store.createDraft(project.id, 'Návrh', 'agent')!
    for (let i = 1; i <= 35; i++) {
      advance(20 * MINUTE)
      store.editDraft(draft.id, { grammarRules: `v${i}` }, { author: 'agent' })
    }
    expect(store.listDraftSnapshots(draft.id).filter((s) => s.kind === 'auto')).toHaveLength(30)
    expect(store.listSnapshots(project.id).filter((s) => s.kind === 'auto')).toHaveLength(1)
  })

  it('a draft snapshot cannot be restored or deleted as a project snapshot', () => {
    const project = store.createProject('Výrazy', expressions())
    const draft = store.createDraft(project.id, 'Návrh', 'agent')!
    store.discardDraft(draft.id)
    const [final] = store.listDraftSnapshots(draft.id)
    expect(store.restoreSnapshot(project.id, final.id)).toBeNull()
    expect(store.deleteSnapshot(project.id, final.id)).toBe(false)
    expect(store.listDraftSnapshots(draft.id)).toHaveLength(1)
  })
})

describe('drafts and their project', () => {
  it('deleting a project deletes its drafts and their snapshots', () => {
    const project = store.createProject('Výrazy', expressions())
    const draft = store.createDraft(project.id, 'Návrh', 'agent')!
    store.discardDraft(draft.id)
    const [final] = store.listDraftSnapshots(draft.id)
    store.deleteProject(project.id)
    expect(store.getDraft(draft.id)).toBeNull()
    expect(store.listDrafts(project.id)).toEqual([])
    expect(store.getSnapshot(final.id)).toBeNull()
  })

  it('duplicating a project copies no drafts', () => {
    const project = store.createProject('Výrazy', expressions())
    store.createDraft(project.id, 'Návrh', 'agent')
    const copy = store.duplicateProject(project.id)!
    expect(store.listDrafts(copy.id)).toEqual([])
    expect(store.listDrafts(project.id)).toHaveLength(1)
  })
})
